def parse_value(buf, at):
    """Decode one value; returns (python value, next offset)."""
    vtype, vlen = struct.unpack_from("<II", buf, at)
    payload = buf[at + 8:at + 8 + vlen]
    end = at + 8 + ((vlen + 7) & ~7)
    if vtype == VALUE_BOOL:
        return payload[0] != 0, end
    if vtype == VALUE_I64:
        return struct.unpack("<q", payload)[0], end
    if vtype == VALUE_F64:
        return struct.unpack("<d", payload)[0], end
    if vtype == VALUE_STR:
        return payload.decode(), end
    if vtype == VALUE_BLOB:
        return BlobHandle(struct.unpack("<Q", payload)[0]), end
    raise ValueError(f"unknown value type {vtype}")


occurrence_blob = None
"""Redeem-and-release for occurrence blobs, installed by the runtime
at import (this module loads no library of its own)."""


def parse_representation(buf, at):
    """The VALUES half of a representation: the count, then that many
    values with blobs redeemed and released.

    Its own function because a drop's clip KIND sits four words and a
    point earlier than its values (docs/dnd-plan.md D1)."""
    count, _reserved = struct.unpack_from("<II", buf, at)
    at += 8
    values = []
    for _ in range(count):
        value, at = parse_value(buf, at)
        if isinstance(value, BlobHandle):
            value = occurrence_blob(value.handle)
        values.append(value)
    return values, at


def parse_clip(buf, at):
    """Decode one representation: the clip kind, then its values.

    Returns (clip, values, next offset). `clip` is a SINGLE member
    of the clip enum and never a mask — you offer many and you
    receive one — and 0 with no values is the universal empty
    answer. Blobs are redeemed to bytes and released here."""
    clip, _reserved = struct.unpack_from("<II", buf, at)
    values, at = parse_representation(buf, at + 8)
    return clip, values, at


def parse_occurrence(buf):
    """Decode one occurrence record (header included).

    Returns (kind, id, keys, payload). keys is [] when id is a
    widget id, else id is a template node id and keys is the
    copy's key path. text is the entry's new content for
    OCC_TEXT_CHANGED, the new state for OCC_TOGGLED, the new
    value for OCC_VALUE_CHANGED, None otherwise.
    """
    _size, kind, _flags = struct.unpack_from("<IHH", buf, 0)
    if kind not in (OCC_BUTTON_CLICKED, OCC_TEXT_CHANGED, OCC_TOGGLED, OCC_VALUE_CHANGED, OCC_CLOSE_REQUESTED, OCC_WINDOW_CLOSED, OCC_ALERT_RESULT, OCC_ENTRY_POPPED, OCC_BACK_REQUESTED, OCC_SECTION_SELECTED, OCC_MENU_ACTIVATED, OCC_MENU_TOGGLED, OCC_MENU_VALUE_CHANGED, OCC_FILE_DIALOG_RESULT, OCC_CLIPBOARD_RESULT, OCC_PASTED, OCC_UNDONE, OCC_REDONE, OCC_SORT_REQUESTED, OCC_DRAW_REQUESTED, OCC_TICK, OCC_DROPPED, OCC_DRAG_ENDED):
        return kind, None, [], None
    if kind == OCC_ALERT_RESULT:
        # The alert's one answer: id + u32 choice (ALERT_CHOICE_*).
        alert, choice = struct.unpack_from("<QI", buf, 8)
        return kind, alert, [], choice
    if kind == OCC_FILE_DIALOG_RESULT:
        dialog, count = struct.unpack_from("<QI", buf, 8)
        at = 32  # past dialog, count, pad, values count, reserved
        files = []
        for _ in range(count):
            handle, at = parse_value(buf, at)
            name, at = parse_value(buf, at)
            local_path, at = parse_value(buf, at)
            files.append((handle, name, local_path))
        return kind, dialog, [], files
    if kind == OCC_CLIPBOARD_RESULT:
        (request,) = struct.unpack_from("<Q", buf, 8)
        clip, values, _at = parse_clip(buf, 16)
        return kind, request, [], (clip, values)
    if kind in (OCC_CLOSE_REQUESTED, OCC_WINDOW_CLOSED, OCC_ENTRY_POPPED, OCC_BACK_REQUESTED):
        # Surface lifecycle records carry the surface id alone —
        # no key path, no payload (derived from the record shapes).
        (surface_id,) = struct.unpack_from("<Q", buf, 8)
        return kind, surface_id, [], None
    if kind in (OCC_SECTION_SELECTED,):
        # Surface-pair records (window, section): the SECOND id
        # keys the handler (they scope to the section); the
        # first rides as the payload.
        window, section = struct.unpack_from("<QQ", buf, 8)
        return kind, section, [], window
    if kind in (OCC_UNDONE, OCC_REDONE,):
        # One undone/redone step: the window, four run
        # lengths, the group's label, then ONE flat values
        # tail the runs cut up — signals, texts, entries,
        # orders, in that order. The payload is the whole
        # RESTORED STATE, never a replay of ops.
        window, n_signals, n_texts, n_entries, n_orders = \
            struct.unpack_from("<QIIII", buf, 8)
        at = 32
        label, at = parse_value(buf, at)
        count, _reserved = struct.unpack_from("<II", buf, at)
        at += 8
        flat = []
        for _ in range(count):
            value, at = parse_value(buf, at)
            flat.append(value)
        i = 0
        signals = []
        for _ in range(n_signals):
            signals.append((flat[i], flat[i + 1]))
            i += 2
        texts = []
        for _ in range(n_texts):
            size, ident, path_len = flat[i:i + 3]
            body = flat[i + 3:i + size]
            i += size
            texts.append((ident, tuple(body[:path_len]), body[path_len]))
        entries = []
        # Arity-first groups: `size` counts itself, so a
        # reader takes it and needs nothing else.
        for _ in range(n_entries):
            size, coll, present, variant, path_len = flat[i:i + 5]
            body = flat[i + 5:i + size]
            i += size
            state = (variant, body[path_len + 1:]) if present else None
            entries.append((coll, tuple(body[:path_len]), body[path_len], state))
        orders = []
        for _ in range(n_orders):
            size, coll, path_len = flat[i:i + 3]
            body = flat[i + 3:i + size]
            i += size
            orders.append((coll, tuple(body[:path_len]), body[path_len:]))
        if i != len(flat):
            raise ValueError("kaya: undo delta has trailing values")
        return kind, window, [], (label, signals, texts, entries, orders)
    ident, path_len = struct.unpack_from("<QI", buf, 8)
    keys = []
    at = 24
    for _ in range(path_len):
        key, at = parse_value(buf, at)
        keys.append(key)
    payload = None
    if kind in (OCC_SORT_REQUESTED,):
        (payload,) = struct.unpack_from("<I", buf, 20)
    if kind in (OCC_TEXT_CHANGED, OCC_TOGGLED, OCC_VALUE_CHANGED, OCC_MENU_TOGGLED, OCC_MENU_VALUE_CHANGED,):
        payload, at = parse_value(buf, at)
    if kind in (OCC_PASTED,):
        clip, values, at = parse_clip(buf, at)
        payload = (clip, values)
    if kind in (OCC_DROPPED,):
        operation, before, anchor_len, clip = struct.unpack_from("<IIII", buf, at)
        at += 16
        x, at = parse_value(buf, at)
        y, at = parse_value(buf, at)
        anchor = []
        for _ in range(anchor_len):
            key, at = parse_value(buf, at)
            anchor.append(key)
        values, at = parse_representation(buf, at)
        payload = (operation, bool(before), (x, y), anchor, clip, values)
    if kind in (OCC_DRAG_ENDED,):
        (payload,) = struct.unpack_from("<I", buf, at)
    if kind in (OCC_DRAW_REQUESTED, OCC_TICK,):
        # The canvas asks carry a run of BARE values after the
        # key path — the assigned size, and a tick's frame time
        # — with no count in front, so they are read until the
        # record ends (docs/canvas-plan.md §3.2.1).
        payload = []
        while at < _size:
            value, at = parse_value(buf, at)
            payload.append(value)
    return kind, ident, keys, payload
